const text = ($json.user_message || "").toLowerCase();

let name = "";
let reason = "";

if (text.includes("for ")) {
  name = text.split("for ")[1].trim();
}

// Capitalize name
name = name.charAt(0).toUpperCase() + name.slice(1);

// Detect reason
if (text.includes("warning")) {
  reason = "Warning";
} else if (text.includes("absence")) {
  reason = "Absence";
} else {
  reason = "Unknown";
}

return [{
  ...$json,
  employee_name: name,
  reason: reason
}];

const text = ($json.user_message || "").toLowerCase();

let intent = "";
let name = "";

// 🔹 Extract employee name
if (text.includes("for")) {
  name = text.split("for")[1].trim();
} else if (text.includes("does")) {
  name = text.split("does")[1].trim();
}

// 🔹 Capitalize name
if (name) {
  name = name.charAt(0).toUpperCase() + name.slice(1);
}

// ====================================================
// INTENT DETECTION (ORDER IS IMPORTANT)
// ====================================================

// 1️⃣ POLICY QUESTION
if (
  text.includes("qué pasa") ||
  text.includes("que pasa") ||
  text.includes("cuántos días") ||
  text.includes("cuantos dias") ||
  text.includes("cuál es") ||
  text.includes("cual es") ||
  text.includes("cómo se") ||
  text.includes("como se") ||
  text.includes("reglamento") ||
  text.includes("vacaciones") ||
  text.includes("ley") ||
  text.includes("derecho") ||
  text.includes("horario") ||
  text.includes("salario") ||
  text.includes("permiso") ||
  text.includes("maternidad") ||
  text.includes("despido") ||
  text.includes("extras") ||
  text.includes("licencia") ||
  text.includes("norma") ||
  text.includes("política") ||
  text.includes("politica") ||
  text.includes("sancion") ||
  text.includes("justificaci") ||
  text.includes("sin justificaci") ||
  text.includes("justificacion")
) {
  intent = "policy_question";
}

// 2️⃣ COUNT RECORDS
else if (
  text.includes("how many") ||
  text.includes("count")
) {
  intent = "count_absence";
}

// 3️⃣ GENERATE NDA
else if (
  text.includes("generate") &&
  text.includes("nda")
) {
  intent = "generate_nda";
}

// 4️⃣ GENERATE SIGNED WARNING
else if (
  text.includes("signed warning")
) {
  intent = "generate_warning_signed";
}

// 5️⃣ GENERATE REFUSED WARNING
else if (
  text.includes("refused warning")
) {
  intent = "generate_warning_refused";
}

// 6️⃣ GENERATE WARNING DOCUMENT
else if (
  text.includes("generate") &&
  text.includes("warning")
) {
  intent = "generate_warning_doc";
}

// 7️⃣ GENERATE CONTRACT
else if (
  text.includes("generate") &&
  text.includes("contract")
) {
  intent = "generate_contract";
}

// 8️⃣ ADD WARNING RECORD
else if (
  text.includes("warning")
) {
  intent = "add_warning";
}

// 9️⃣ ADD ABSENCE RECORD
else if (
  text.includes("absence")
) {
  intent = "add_absence";
}

return [
  {
    json: {
      ...$json,
      intent,
      employee_name: name
    }
  }
];

