parameters.jsCode:
const text = ($json.user_message || "").toLowerCase();

let name = "";
let countType = "Absence";

if (text.includes("does")) {
  const afterDoes = text.split("does")[1].trim();
  name = afterDoes.split(" ")[0].trim();
}

name = name.charAt(0).toUpperCase() + name.slice(1);

if (text.includes("warning")) {
  countType = "Warning";
} else if (text.includes("absence")) {
  countType = "Absence";
} else if (text.includes("sick")) {
  countType = "Sick leave";
}

return [{
  json: {
    ...$json,
    employee_name: name,
    countType: countType
  }
}];

const allItems = $input.all();

const employeeName = $('Parse Count Request').first().json.employee_name.trim().toLowerCase();
const managerArea = $('Edit Fields').first().json.manager_area.trim().toLowerCase();
const countType = $('Parse Count Request').first().json.countType.trim();

// Find employee's area
const employeeRows = allItems.filter(item => {
  const name = (item.json['Employee Name'] || '').trim().toLowerCase();
  return name === employeeName;
});

const employeeArea = employeeRows.length > 0 
  ? (employeeRows[0].json['Area'] || '').trim().toLowerCase() 
  : '';

// Permission check
const hasAccess = employeeArea === managerArea;

// Count matching rows
const matched = allItems.filter(item => {
  const name = (item.json['Employee Name'] || '').trim().toLowerCase();
  const area = (item.json['Area'] || '').trim().toLowerCase();
  const reason = (item.json['Reason'] || '').trim();
  return name === employeeName && area === managerArea && reason === countType;
});

// Debug info
return [{
  json: {
    employee_name: $('Parse Count Request').first().json.employee_name,
    countType: countType,
    count: matched.length,
    hasAccess: hasAccess,
    employeeArea: employeeArea,
    managerArea: managerArea
  }
}];
